    CASE (s.sec_type) WHEN 'DEPOSIT' THEN 'CASH_BULLION_DEPOSITS' WHEN 'SHARES' THEN 'SHARES_BONDS_SECURITIES' WHEN 'STOCK' THEN 'INVENTORY' WHEN 'RECEIVABLES' THEN 'ACCOUNTS_RECEIVABLE' WHEN 'PLANT' THEN 'PLANT_MACHINERY' WHEN 'LAND' THEN 'LAND_BUILDINGS' ELSE (s.sec_type) END AS security_type,
